/** `~5 trips`; `~? trips` until the pace is known; `~99+` at the cap. */
export function rangeText(n: number | undefined, unit: readonly [string, string]): string {
  if (n === undefined) return `~? ${unit[1]}`
  return `~${n >= 99 ? '99+' : n} ${n === 1 ? unit[0] : unit[1]}`
}

